# Tests for the CV parser.   Run from the cv_parser folder:   python -m pytest tests -v
# The test CVs (PDF) are generated by tests/make_test_cvs.py, so no personal data is needed.
import os
import re
import sys

import pytest

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))

import cv_parsing as cv                       # noqa: E402
from make_test_cvs import build_all           # noqa: E402

FIELDS = ("skills", "education", "experience", "certifications", "languages", "projects")


@pytest.fixture(scope="session")
def pdfs(tmp_path_factory):
    return build_all(str(tmp_path_factory.mktemp("cvs")))


@pytest.fixture(scope="session")
def results(pdfs):
    return {name: cv.process_cv(path) for name, path in pdfs.items()}


def joined(items):
    return " || ".join(items)


# ---------------- 1) expected content per layout ----------------
def test_single_column_alternative_headings(results):
    r = results["single_column"]
    assert r["skills"] == ["Python", "Java", "SQL", "Django", "React", "FastAPI", "Git", "Docker", "Linux"]
    assert len(r["education"]) == 1 and "Bachelor of Computer Science" in r["education"][0]
    assert "King Abdulaziz University" in r["education"][0]
    assert len(r["experience"]) == 2
    assert "Software Developer - ABC Technologies" in r["experience"][0] and "Jan 2022 - Present" in r["experience"][0]
    assert r["certifications"] == ["AWS Certified Cloud Practitioner - 2023", "Google Data Analytics Certificate"]
    assert r["languages"] == ["Arabic (Native)", "English (Fluent)"]
    assert len(r["projects"]) == 1 and r["projects"][0].startswith("Smart Attendance System")


def test_two_columns_sidebar_on_the_left(results):
    r = results["two_col_left"]
    assert r["skills"] == ["Python", "SQL", "Power BI", "Machine Learning", "Communication"]
    assert r["languages"] == ["English", "Arabic"]
    assert r["certifications"] == ["Azure Fundamentals AZ-900"]
    assert len(r["education"]) == 2
    assert "Master of Data Science" in r["education"][0] and "Imam University" in r["education"][0]
    assert "Bachelor of Statistics" in r["education"][1]
    assert len(r["experience"]) == 2 and r["experience"][0].startswith("Data Analyst, Tamkeen Co.")
    assert len(r["projects"]) == 1


def test_two_columns_sidebar_on_the_right(results):
    r = results["two_col_right"]
    assert r["skills"] == ["Networking", "Cisco IOS", "Firewalls", "Linux", "Python scripting"]
    assert r["languages"] == ["Arabic (Native)", "English (Good)"]
    assert r["certifications"] == ["CCNA - Cisco, 2019"]
    assert len(r["education"]) == 1 and "Taibah University" in r["education"][0]
    assert len(r["experience"]) == 1 and "Saudi Telecom" in r["experience"][0]


def test_inline_headings_and_two_pages(results):
    r = results["inline_two_pages"]
    assert r["skills"] == ["SEO", "Google Analytics", "Content Writing", "Adobe Photoshop"]
    assert r["languages"] == ["Arabic", "English", "French"]
    assert "Effat University" in r["education"][0]          # education is on page 2
    assert "BrightAds" in r["experience"][0]


def test_unknown_heading_closes_the_skills_section(results):
    r = results["unknown_heading"]
    assert r["skills"] == ["Python", "SQL", "Git", "Excel", "Power BI"]     # nothing from "Community involvement"
    assert "Experiance" not in joined(r["skills"])                           # misspelled heading still understood
    assert "Zain KSA" in r["experience"][0]
    assert "Qassim University" in r["education"][0]
    assert "bootcamp" not in joined(r["experience"] + r["education"])        # the unknown section is not extracted


def test_no_sections_returns_empty_lists_not_invented_data(results):
    r = results["no_sections"]
    for field in FIELDS:
        assert r[field] == []
    assert r["parse_status"] == "failed"


# ---------------- 2) education / experience must NEVER end up in skills ----------------
BAD_IN_SKILLS = re.compile(
    r"(?i)\b(university|college|institute|bachelor|master of|diploma|gpa|graduat\w*)\b|(19|20)\d{2}|"
    r"\b(developed|managed|responsible for|worked|led|built|analysed|resolved)\b")


@pytest.mark.parametrize("name", ["single_column", "two_col_left", "two_col_right", "inline_two_pages",
                                  "unknown_heading", "no_sections"])
def test_skills_never_contain_education_or_experience(results, name):
    r = results[name]
    for skill in r["skills"]:
        assert not BAD_IN_SKILLS.search(skill), f"{skill!r} looks like education/experience"
        assert len(skill.split()) <= 4 and not skill.endswith("."), f"{skill!r} is a sentence, not a skill"
    for line in r["education"] + r["experience"]:           # no whole entry (or line) is also a skill
        assert line not in r["skills"]
    assert not set(s.lower() for s in r["skills"]) & set(l.lower() for l in r["languages"])


@pytest.mark.parametrize("name", ["single_column", "two_col_left", "two_col_right", "inline_two_pages", "unknown_heading"])
def test_education_and_experience_do_not_contain_each_other(results, name):
    r = results[name]
    assert not re.search(r"(?i)university|college|bachelor|b\.sc|master of", joined(r["experience"]))
    for entry in r["education"]:
        assert not re.search(r"(?i)\b(developed|managed|configured|analysed|resolved|planned)\b", entry)


def test_leaked_text_is_filtered_even_if_the_section_is_wrong():
    """Safety net: even if education / experience lines land in the skills section, they are not skills."""
    leaked = [
        "Python, Java, SQL",
        "Bachelor of Computer Science - King Saud University 2016 - 2020",
        "Software Developer at ABC Company",
        "Software Developer - ABC Technologies | Jan 2022 - Present",
        "Developed REST APIs using Python and Django for the payments team.",
        "Managed a team of 3 engineers and improved deployment time by 40%.",
        "GPA: 4.5/5",
    ]
    skills, languages = cv.clean_skills(leaked)
    assert skills == ["Python", "Java", "SQL"]              # work descriptions are dropped, nothing is rescued from them
    assert languages == []


def test_skills_paragraph_gives_names_not_sentences():
    skills, _ = cv.clean_skills(["I am proficient in Python and SQL, and I have built many web applications for clients."])
    assert skills == ["Python", "SQL"]


def test_lines_copied_from_other_sections_are_never_skills():
    forbidden = {cv._norm("Network Security Analyst")}
    skills, _ = cv.clean_skills(["Network Security Analyst", "Wireshark"], forbidden=forbidden)
    assert skills == ["Wireshark"]


def test_skill_names_with_special_characters_survive():
    skills, _ = cv.clean_skills(["C++, C#, Node.js, CI/CD, TCP/IP, MS Office (Word, Excel), Scrum Master, Scikit-learn"])
    assert skills == ["C++", "C#", "Node.js", "CI/CD", "TCP/IP", "MS Office (Word, Excel)", "Scrum Master", "Scikit-learn"]


def test_human_languages_inside_skills_move_to_languages():
    skills, languages = cv.clean_skills(["Python, English, Arabic"])
    assert skills == ["Python"] and languages == ["English", "Arabic"]


# ---------------- 3) headings ----------------
@pytest.mark.parametrize("text, section", [
    ("Technical Skills", "skills"), ("TECHNICAL SKILLS:", "skills"), ("Core Competencies", "skills"),
    ("Programming Languages", "skills"), ("Languages & Frameworks", "skills"),
    ("Professional Experience", "experience"), ("Employment History", "experience"), ("Work History", "experience"),
    ("Academic Background", "education"), ("Education & Training", "education"), ("Educational Background", "education"),
    ("Courses & Certificates", "certifications"), ("Licenses and Certifications", "certifications"),
    ("Academic Projects", "projects"), ("Languages", "languages"), ("Career Objective", "summary"),
    ("Hobbies", "other"), ("المهارات", "skills"), ("الخبرات العملية", "experience"),
])
def test_alternative_headings(text, section):
    assert cv.heading_section(text, True) == section


@pytest.mark.parametrize("text", [
    "Experience with Python and Django", "Project Management", "Python", "Skills used: Python, Django",
    "Developed REST APIs using Python.", "Bachelor of Computer Science", "Software Developer at ABC Company"])
def test_normal_lines_are_not_headings(text):
    assert cv.heading_section(text, True) is None


def test_skills_inline_heading_and_language_category_label():
    sections = cv.split_sections(["Skills: Python, SQL", "Work Experience", "Developer at ABC", "Languages: Python, Java"])
    assert sections["skills"] == ["Python, SQL"]
    assert sections["experience"] == ["Developer at ABC", "Languages: Python, Java"]   # not a language section
    sections = cv.split_sections(["Languages: English, Arabic"])
    assert sections["languages"] == ["English, Arabic"]


def test_references_end_the_last_section():
    sections = cv.split_sections(["Skills", "Python", "References available upon request."])
    assert sections["skills"] == ["Python"]


# ---------------- 4) layout ----------------
def test_two_columns_detected_and_single_column_not(pdfs):
    import pymupdf

    def gutter(name):
        page = pymupdf.open(pdfs[name])[0]
        pieces = [p for b in page.get_text("dict")["blocks"] if b.get("type") == 0 for l in b["lines"]
                  for p in cv._pieces_of_line(l, 0)]
        return cv.find_gutter(pieces, page.rect.width)

    assert gutter("two_col_left") is not None
    assert gutter("two_col_right") is not None
    assert gutter("single_column") is None


def test_reading_order_keeps_each_column_together(pdfs):
    lines = [l.text for l in cv.extract_lines(pdfs["two_col_left"])]
    assert lines.index("SKILLS") < lines.index("Communication") < lines.index("WORK EXPERIENCE") < lines.index("EDUCATION")
    assert lines.index("LANGUAGES") < lines.index("English") < lines.index("WORK EXPERIENCE")


# ---------------- 5) the parser works without spaCy too ----------------
def test_results_are_the_same_without_spacy(pdfs, monkeypatch, results):
    monkeypatch.setattr(cv, "get_nlp", lambda: None)
    for name in ("single_column", "two_col_left", "two_col_right"):
        again = cv.process_cv(pdfs[name])
        for field in FIELDS:
            assert again[field] == results[name][field], (name, field)


# ---------------- 6) output format + compatibility with the FastAPI test pages ----------------
def test_output_format(results):
    r = results["single_column"]
    for field in FIELDS:
        assert isinstance(r[field], list) and all(isinstance(x, str) for x in r[field])
    for key in ("parse_status", "removed", "clean_text", "summary"):
        assert key in r
    assert "omar.hassan@example.com" not in r["clean_text"] and "+966" not in r["clean_text"]


def test_test_page_and_api_still_work(pdfs, tmp_path):
    from fastapi.testclient import TestClient
    import api
    import test_app

    client = TestClient(test_app.app)
    with open(pdfs["two_col_left"], "rb") as f:
        page = client.post("/", files={"cv": ("cv.pdf", f, "application/pdf")}, data={"full_name": ""})
    assert page.status_code == 200 and "Power BI" in page.text and "Master of Data Science" in page.text

    api_client = TestClient(api.app)
    body = api_client.post("/api/cv/process", json={"pdf_path": pdfs["two_col_right"]}).json()
    assert body["skills"][0] == "Networking" and body["parse_status"] == "success"
